from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import outage_refund
from ledgerly.errors import BillingError
from ledgerly.models import Payment

T0 = datetime(2026, 10, 1, tzinfo=timezone.utc)
def mk(status="captured", amt="80.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0)

p = mk()
assert outage_refund(p, Decimal("30.00"), T0) is p
assert p.refunded_amount == Decimal("30.00") and p.status == "captured"
outage_refund(p, Decimal("50.00"), T0)
assert p.refunded_amount == Decimal("80.00") and p.status == "refunded"
print("partial/full ok")

for bad in [Decimal("0"), Decimal("-1")]:
    try: outage_refund(mk(), bad, T0); print("FAIL")
    except BillingError as e: print("non-positive:", e.code)

try: outage_refund(mk(), Decimal("81.00"), T0); print("FAIL")
except BillingError as e: print("exceeds:", e.code)

try: outage_refund(mk("authorized"), Decimal("1.00"), T0); print("FAIL")
except BillingError as e: print("state:", e.code)

# idempotency
audit.clear()
p = mk()
outage_refund(p, Decimal("10.00"), T0, idempotency_key="k1")
outage_refund(p, Decimal("10.00"), T0, idempotency_key="k1")
assert p.refunded_amount == Decimal("10.00")
assert len(audit.events("payment_refunded")) == 1
print("idempotency ok; audit:", audit.events("payment_refunded"))
EOF"}

